cd /tmp && cat > /tmp/e2e_auth_cert.mjs <<'JS'
import fs from 'node:fs';

const URL_BASE = 'https://kvclcdjmjghndxsngfzb.supabase.co';
const SVC = fs.readFileSync('/tmp/svc.txt', 'utf8').trim();
const ANON = JSON.parse(fs.readFileSync('/tmp/resolved.json', 'utf8')).key;
const BAD_ANON = (fs.readFileSync('/tmp/badkey.txt', 'utf8') || '').trim();
const OWNER_ID = '9b280e15-f9fd-459f-bf2d-530b1ed84cb1';

const results = [];
let userId = null;
const email = `ivx.cert.${Date.now()}@ivxholding.com`;
const password = `Ivx!Cert${Math.random().toString(36).slice(2, 10)}A1`;

function rec(step, name, pass, detail) {
  results.push({ step, name, status: pass ? 'PASS' : 'FAIL', detail });
  console.log(`${pass ? 'PASS' : 'FAIL'} [${String(step).padStart(2, '0')}] ${name} :: ${detail}`);
}

const admin = (p, init = {}) => fetch(`${URL_BASE}${p}`, {
  ...init,
  headers: { apikey: SVC, Authorization: `Bearer ${SVC}`, 'Content-Type': 'application/json', ...(init.headers || {}) },
});
const anon = (p, init = {}, key = ANON) => fetch(`${URL_BASE}${p}`, {
  ...init,
  headers: { apikey: key, 'Content-Type': 'application/json', ...(init.headers || {}) },
});

try {
  let r = await anon('/auth/v1/settings');
  rec(1, 'Fixed anon key accepted by GoTrue', r.status === 200, `HTTP ${r.status}`);

  if (BAD_ANON) {
    r = await anon('/auth/v1/settings', {}, BAD_ANON);
    const b = await r.json().catch(() => ({}));
    rec(2, 'Old demo env key correctly rejected (regression proof)', r.status === 401, `HTTP ${r.status} ${b.message || ''}`);
  } else {
    rec(2, 'Old demo env key correctly rejected (regression proof)', false, 'bad key unavailable');
  }

  r = await admin('/auth/v1/admin/users', { method: 'POST', body: JSON.stringify({ email, password, email_confirm: true }) });
  const created = await r.json();
  userId = created.id ?? null;
  rec(3, 'Provision controlled QA account', r.status === 200 && !!userId, `HTTP ${r.status} id=${userId ?? 'none'}`);

  r = await anon('/auth/v1/token?grant_type=password', { method: 'POST', body: JSON.stringify({ email, password }) });
  const session = await r.json();
  const accessToken = session.access_token ?? null;
  const refreshToken = session.refresh_token ?? null;
  rec(4, 'Password sign-in returns live session', r.status === 200 && !!accessToken, `HTTP ${r.status} token=${accessToken ? 'issued' : 'none'}`);

  r = await anon('/auth/v1/user', { headers: { Authorization: `Bearer ${accessToken}` } });
  const me = await r.json();
  rec(5, 'Session identity resolves', r.status === 200 && me.email === email, `HTTP ${r.status} email_match=${me.email === email}`);

  r = await anon('/auth/v1/token?grant_type=refresh_token', { method: 'POST', body: JSON.stringify({ refresh_token: refreshToken }) });
  const refreshed = await r.json();
  rec(6, 'Refresh token rotation works', r.status === 200 && !!refreshed.access_token, `HTTP ${r.status}`);

  r = await anon('/auth/v1/logout', { method: 'POST', headers: { Authorization: `Bearer ${refreshed.access_token ?? accessToken}` } });
  rec(7, 'Sign-out revokes session', r.status === 204 || r.status === 200, `HTTP ${r.status}`);

  r = await anon('/auth/v1/token?grant_type=password', { method: 'POST', body: JSON.stringify({ email, password: 'DefinitelyWrong!123' }) });
  const badLogin = await r.json();
  rec(8, 'Wrong password yields credential error, not API-key error', r.status === 400 && badLogin.error_code === 'invalid_credentials', `HTTP ${r.status} code=${badLogin.error_code}`);

  r = await admin(`/auth/v1/admin/users/${OWNER_ID}`);
  const owner = await r.json();
  const ownerOk = r.status === 200 && !!owner.email_confirmed_at && !owner.banned_until;
  rec(9, 'Owner account active, confirmed, unbanned', ownerOk, `confirmed=${!!owner.email_confirmed_at} banned=${owner.banned_until ?? 'none'}`);

  r = await admin('/auth/v1/admin/generate_link', { method: 'POST', body: JSON.stringify({ type: 'magiclink', email: owner.email }) });
  const link = await r.json();
  rec(10, 'Owner auth pipeline issues valid login token', r.status === 200 && !!link.hashed_token, `HTTP ${r.status} token=${link.hashed_token ? 'issued' : 'none'}`);

  r = await anon('/rest/v1/', { headers: { Authorization: `Bearer ${ANON}` } });
  rec(11, 'REST/PostgREST reachable with fixed key', r.status === 200, `HTTP ${r.status}`);
} catch (e) {
  rec(99, 'Harness execution', false, e.message);
} finally {
  if (userId) {
    const del = await admin(`/auth/v1/admin/users/${userId}`, { method: 'DELETE' });
    rec(12, 'QA account cleanup', del.status === 200 || del.status === 204, `HTTP ${del.status}`);
  }
}

const passed = results.filter((x) => x.status === 'PASS').length;
console.log(`\nTOTAL ${passed}/${results.length} PASS`);
fs.writeFileSync('/tmp/e2e_auth_results.json', JSON.stringify({ passed, total: results.length, results }, null, 2));
process.exit(passed === results.length ? 0 : 1);
